const query = $json.query;
const invalid = (code, message) => [{ json: { valid: false, statusCode: 400, response: { error: { code, message } } } }];

if (!query || typeof query !== 'object' || Array.isArray(query)) {
  return invalid('INVALID_QUERY', 'Query parameters type and value are required.');
}

const unknown = Object.keys(query).filter((key) => !['type', 'value'].includes(key));
if (unknown.length > 0) {
  return invalid('UNKNOWN_QUERY_PARAMETER', 'Only type and value query parameters are accepted.');
}

if (query.type !== 'url' && query.type !== 'wallet') {
  return invalid('INVALID_TYPE', 'type must be exactly url or wallet.');
}
if (typeof query.value !== 'string' || !query.value.trim()) {
  return invalid('INVALID_VALUE', 'value must be a non-empty string.');
}

const value = query.value.trim();
if (/[\u0000-\u001f\u007f]/.test(value)) {
  return invalid('INVALID_VALUE', 'value must not contain control characters.');
}

if (query.type === 'url') {
  if (value.length > 2048) {
    return invalid('INVALID_URL', 'URL exceeds the 2048-character limit.');
  }

  const match = /^(https?):\/\/([^/?#\s]+)(?:[/?#][^\s]*)?$/i.exec(value);
  const authority = match?.[2] || '';
  if (!match || authority.includes('@') || authority.includes('\\')) {
    return invalid('INVALID_URL', 'A credential-free HTTP(S) URL is required.');
  }

  let hostname = authority;
  let port = '';
  if (authority.startsWith('[')) {
    const ipv6 = /^(\[[0-9a-f:.]+\])(?::(\d{1,5}))?$/i.exec(authority);
    if (!ipv6) {
      return invalid('INVALID_URL', 'A valid HTTP(S) URL is required.');
    }
    hostname = ipv6[1];
    port = ipv6[2] || '';
  } else {
    const host = /^([^:]+)(?::(\d{1,5}))?$/.exec(authority);
    if (!host) {
      return invalid('INVALID_URL', 'A valid HTTP(S) URL is required.');
    }
    hostname = host[1];
    port = host[2] || '';
  }

  if (!hostname || /[<>\[\]{}|^`"\s]/.test(hostname) || (port && Number(port) > 65535)) {
    return invalid('INVALID_URL', 'A valid HTTP(S) URL is required.');
  }
} else if (!/^0x[0-9a-fA-F]{40}$/.test(value)) {
  return invalid('INVALID_WALLET', 'A valid EVM wallet address is required.');
}

return [{ json: { valid: true, type: query.type, value } }];

const statusCode = Number($json.statusCode);
const body = $json.body && typeof $json.body === 'object' ? $json.body : {};

if (statusCode !== 200) {
  const publicStatus = statusCode >= 400 && statusCode < 500 ? statusCode : 502;
  const code = publicStatus === 400 ? 'INVALID_REQUEST' : publicStatus === 401 ? 'BRIDGE_UNAUTHORIZED' : 'BLOCKCHAIN_UNAVAILABLE';
  const message = publicStatus === 400 ? 'Invalid check request.' : 'Blockchain check is temporarily unavailable.';
  return [{ json: { statusCode: publicStatus, response: { error: { code, message } } } }];
}

if (body.blacklisted !== true) {
  return [{ json: { statusCode: 200, response: { blacklisted: false } } }];
}

return [{
  json: {
    statusCode: 200,
    response: {
      blacklisted: true,
      category: body.category,
      score: body.score,
      since: body.since,
      txHash: body.txHash
    }
  }
}];
